def e(x):return html.escape(str(x))
def money(x):return ('−' if x<0 else '')+'$'+f'{abs(x):,.0f}'
def p(x):return '<0.001' if x<.001 else f'{x:.3f}'
def val(spec,outcome,term):return c[(c.spec==spec)&(c.outcome==outcome)&(c.term==term)].iloc[0]
def table(headers,rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+e(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def effect(r):
    log=r.outcome=='logit'
    v=lambda x:f'{x:.3f}' if log else money(x)
    return v(r.effect)+' ['+v(r.effect_lo)+', '+v(r.effect_hi)+']'
def core_table(outcome):
    d=c[(c.outcome==outcome)&c.spec.isin(['All','Standalone','System'])]
    terms=d[d.spec=='All'].term.tolist(); rows=[]
    for t in terms:
        row=[e(d[d.term==t].iloc[0].label)]
        for spec in ['All','Standalone','System']:
            r=d[(d.term==t)&(d.spec==spec)].iloc[0]
            b=f'{r.effect:.3f}' if outcome=='logit' else money(r.effect)
            row.append(f'{b}<br><small>95% CI {r.effect_lo:.3f}–{r.effect_hi:.3f}; p {p(r.p)}</small>' if outcome=='logit' else f'{b}<br><small>95% CI {money(r.effect_lo)} to {money(r.effect_hi)}; p {p(r.p)}</small>')
        rows.append(row)
    rows += [['N']+[str(int(d[d.spec==s].iloc[0].n)) for s in ['All','Standalone','System']],
             ['McFadden pseudo-R²' if outcome=='logit' else 'R²']+[f'{d[d.spec==s].iloc[0]["fit"]:.3f}' for s in ['All','Standalone','System']]]
    return table(['Predictor','All','Standalone','System'],rows)

