# Fully self-contained dashboard for local use: no server or network is needed.
dashboard=(SITE/'index.html').read_text()
app=(SITE/'app.js').read_text().replace("const response=await fetch('data.json');if(!response.ok)throw Error('Data did not load');DATA=await response.json();", "DATA=JSON.parse(document.getElementById('embedded-data').textContent);")
dashboard=dashboard.replace('<link rel="stylesheet" href="style.css">','<style>'+(SITE/'style.css').read_text()+'</style>')
dashboard=dashboard.replace('href="report.html','href="camp_replication_report.html').replace('href="replication-package.zip"','href="camp-replication-package.zip"')
embedded=(SITE/'data.json').read_text().replace('</','<\\/')
